const listConversationsWithPendingReports = `-- name: ListConversationsWithPendingReports :many
SELECT DISTINCT rep.parent_id
FROM subagent_reports rep
         JOIN conversations c ON c.id = rep.conversation_id
         JOIN conversations p ON p.id = rep.parent_id
WHERE rep.delivered_message_id IS NULL
  AND NOT rep.via_tool
  AND c.background
  AND p.deleted_at IS NULL
LIMIT 100
`

// The sweep's work: conversations a report is waiting for.
func (q *Queries) ListConversationsWithPendingReports(ctx context.Context) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listConversationsWithPendingReports)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var parent_id uuid.UUID
		if err := rows.Scan(&parent_id); err != nil {
			return nil, err
		}
		items = append(items, parent_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listIdleSubagentInboxes = `-- name: ListIdleSubagentInboxes :many
SELECT DISTINCT i.conversation_id
FROM subagent_inbox i
         JOIN conversations c ON c.id = i.conversation_id
WHERE NOT c.stopped_by_user
  AND NOT EXISTS (SELECT 1 FROM runs r WHERE r.conversation_id = i.conversation_id AND r.status = 'running')
LIMIT 100
`

