const lockSubagentSlots = `-- name: LockSubagentSlots :exec
SELECT pg_advisory_xact_lock(hashtextextended('subagent_slots:' || $1::text, 23))
`

// Held until the transaction ends, like LockRunSlots: counting a person's
// sub-agent runs and starting one is one step, on one server or several.
func (q *Queries) LockSubagentSlots(ctx context.Context, userID string) error {
	_, err := q.db.Exec(ctx, lockSubagentSlots, userID)
	return err
}

