const takeReportForTool = `-- name: TakeReportForTool :one
UPDATE subagent_reports
SET via_tool = true
WHERE run_id = $1
  AND delivered_message_id IS NULL
RETURNING run_id, conversation_id, parent_id, state, report, duration_ms, via_tool, delivered_message_id, created_at
`

// A foreground call takes its sub-agent's report as its result, unless it was
// delivered some other way first. Taking it again is the same call replayed
// (the claim is committed apart from the call's result, and a process can die
// in between): only the call waiting on this run takes it, so it gets it back.
func (q *Queries) TakeReportForTool(ctx context.Context, runID uuid.UUID) (SubagentReport, error) {
	row := q.db.QueryRow(ctx, takeReportForTool, runID)
	var i SubagentReport
	err := row.Scan(
		&i.RunID,
		&i.ConversationID,
		&i.ParentID,
		&i.State,
		&i.Report,
		&i.DurationMs,
		&i.ViaTool,
		&i.DeliveredMessageID,
		&i.CreatedAt,
	)
	return i, err
}

const takeSubagentInbox = `-- name: TakeSubagentInbox :many
WITH taken AS (
    DELETE FROM subagent_inbox
        WHERE conversation_id = $1
        RETURNING id, conversation_id, content, created_at)
SELECT id, conversation_id, content, created_at
FROM taken
ORDER BY created_at, id
`

type TakeSubagentInboxRow struct {
	ID             uuid.UUID          `json:"id"`
	ConversationID uuid.UUID          `json:"conversation_id"`
	Content        string             `json:"content"`
	CreatedAt      pgtype.Timestamptz `json:"created_at"`
}

// The messages waiting for a sub-agent, taken: the caller writes them into its
// transcript in the same transaction.
func (q *Queries) TakeSubagentInbox(ctx context.Context, conversationID uuid.UUID) ([]TakeSubagentInboxRow, error) {
	rows, err := q.db.Query(ctx, takeSubagentInbox, conversationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TakeSubagentInboxRow{}
	for rows.Next() {
		var i TakeSubagentInboxRow
		if err := rows.Scan(
			&i.ID,
			&i.ConversationID,
			&i.Content,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
